def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)

    # Create a 2D DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: transforming empty string to b[:j] requires j insertions
    for j in range(n + 1):
        dp[0][j] = j

    # Base cases: transforming a[:i] to empty string requires i deletions
    for i in range(m + 1):
        dp[i][0] = i

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )

    return dp[m][n]
